window.docContents[218].resolve({"/Gamma-Function/___5___1-Special-Notation/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___1-Special-Notation--___5___1-Special-Notation":{"contents":"Section 5.1 is the notation contract for the rest of Chapter 5.  It does not number\nequations: instead, it fixes the domains of the recurring indices and variables, the\nmeaning of the small parameter δ, the Euler constant γ, and the names used for the\nprincipal Gamma-family functions.  The declarations below keep those conventions visible\nwhile reusing Mathlib's functions in every later section.\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Gamma Function\u0009§5.1 Special Notation","header":"§5.1 Special Notation","id":"/Gamma-Function/___5___1-Special-Notation/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___1-Special-Notation--___5___1-Special-Notation"}});